#!/usr/bin/env python3
# pdf2escpos — CUPS filter: application/pdf -> application/vnd.cups-raw (ESC/POS)
# Reads a PDF, extracts text, wraps to receipt width, writes ESC/POS to stdout.
# designed to be run behind CUPS on a linux server
# to format text-containing PDFs for ESC/POS thermal receipt printers
# reviewed, edited, debugged by Andy Maxwell
# generated by ChatGPT on 2024-09-22

import io
import os
import re
import sys
import shlex
import subprocess
import textwrap
import unicodedata
import xml.etree.ElementTree as ET
from collections import Counter
from dataclasses import dataclass
from functools import lru_cache
from typing import Callable, Dict, List, Optional, Tuple

try:
    from PIL import Image, ImageOps
except ImportError:  # text still prints without Pillow
    Image = ImageOps = None  # type: ignore

# ---------- Printer profiles ----------
# Each profile describes one printer model. Settings from the PPD, the job
# options and ESCPOS_* env vars are applied on top of the profile defaults.
#
# codepages: PPD option value -> (Python codec, ESC t n value for this printer)
PROFILES = {
    "epson-tm-t20ii": {
        "cols": 48,          # 80mm roll, Font A (12x24)
        "cols_58mm": 35,     # 58mm roll, Font A, per Epson spec
        "dots": 576,         # print width in dots on 80mm paper (203 dpi)
        "dots_58mm": 416,    # 58mm paper, rounded down to a whole byte
        "image_gamma": 0.8,  # lighten midtones; thermal dots spread a little
        "codepages": {
            "cp437": ("cp437", 0),     # PC437 USA
            "cp858": ("cp858", 19),    # PC858 Euro
            "latin-1": ("cp1252", 16), # WPC1252, the printer's closest Latin-1 table
        },
        "default_codepage": "cp437",
        "cut": b'\x1b\x6d',  # ESC m partial cut; known to work on the TM-T20II
        "red": False,       # single-color thermal; red text prints bold
    },
}
DEFAULT_PROFILE = "epson-tm-t20ii"

# ESCPOS_* env vars, kept for command-line testing. They override everything.
ENV_OPTIONS = {
    "ESCPOS_PROFILE": "EscposProfile",
    "ESCPOS_COLS": "EscposCols",
    "ESCPOS_CODEPAGE": "EscposCodepage",
}

MAX_COPIES = 100
PRINT_MODES = ("auto", "text", "image")
DITHER_METHODS = ("auto", "atkinson", "floyd-steinberg", "threshold")
DENSE_LINE_SPACING = False  # set True for tighter lines on long receipts
CUT_AT_JOB_END = True
# Simple directive markers you can print from your app:
# [CENTER], [LEFT], [RIGHT]
# [B], [/B] for bold, [U], [/U] underline
# [CUT] on a line by itself
# (markers work when a line of the PDF starts with one)
# --------------------------------

# ESC/POS Control Characters
ESC = b'\x1b'
GS  = b'\x1d'
FS  = b'\x1c'

# ESC/POS Constants
FONT_A = b'\x00'
FONT_B = b'\x01'
DENSE_LINE_SPACING_DOTS = b'\x16'  # 22-dot line spacing


def log(level: str, msg: str) -> None:
    """Write a CUPS-style log line (DEBUG/INFO/WARNING/ERROR) to stderr."""
    sys.stderr.write(f"{level}: pdf2escpos: {msg}\n")


# ---------- Settings ----------

@dataclass
class Settings:
    profile_name: str
    profile: dict
    cols: int
    codepage: str       # PPD option value, e.g. "cp437"
    codec: str          # Python codec used to encode text
    codepage_n: int     # ESC t n value
    left: int
    right: int
    cut_feed_lines: int
    header: str
    footer: str
    copies: int
    print_title: bool
    dots: int           # image width in dots
    print_mode: str     # auto: pages without text print as images
    dither: str


def bounded_int(value: Optional[str], default: int, lo: int, hi: int) -> int:
    try:
        n = int(value) if value is not None else default
    except ValueError:
        return default
    return n if lo <= n <= hi else default


def parse_options(options: str) -> Dict[str, str]:
    """Parse the CUPS options string (argv[5]): 'name=value name2="a b" flag'."""
    try:
        words = shlex.split(options)
    except ValueError:
        words = options.split()
    parsed = {}
    for word in words:
        name, sep, value = word.partition("=")
        parsed[name] = value if sep else "true"
    return parsed


def read_ppd_defaults(ppd_path: Optional[str]) -> Dict[str, str]:
    """Read '*DefaultName: value' lines from the queue's PPD (CUPS sets $PPD)."""
    defaults = {}
    if not ppd_path:
        return defaults
    try:
        with open(ppd_path, encoding="latin-1") as f:
            for line in f:
                if line.startswith("*Default"):
                    name, _, value = line[len("*Default"):].partition(":")
                    defaults[name.strip()] = value.strip().strip('"')
    except OSError as e:
        log("WARNING", f"cannot read PPD {ppd_path}: {e}")
    return defaults


def resolve_settings(argv: List[str], env: Dict[str, str]) -> Settings:
    # Lowest to highest priority: profile defaults, PPD defaults, job options, env vars
    raw = read_ppd_defaults(env.get("PPD"))
    raw.update(parse_options(argv[5] if len(argv) > 5 else ""))
    for var, name in ENV_OPTIONS.items():
        if env.get(var):
            raw[name] = env[var]

    profile_name = raw.get("EscposProfile", DEFAULT_PROFILE)
    if profile_name not in PROFILES:
        log("WARNING", f"unknown profile {profile_name!r}, using {DEFAULT_PROFILE}")
        profile_name = DEFAULT_PROFILE
    profile = PROFILES[profile_name]

    cols = bounded_int(raw.get("EscposCols"), profile["cols"], 1, 1000)
    dots = profile["dots"]
    # A 58mm roll can't fit more than the profile's 58mm column count
    page_size = raw.get("PageSize") or raw.get("PageRegion") or raw.get("media") or ""
    if "58" in page_size:
        cols = min(cols, profile["cols_58mm"])
        dots = profile["dots_58mm"]

    def choice(name: str, allowed: Tuple[str, ...]) -> str:
        value = raw.get(name, allowed[0]).lower()
        if value not in allowed:
            log("WARNING", f"{name}={value!r} not one of {', '.join(allowed)}, using {allowed[0]}")
            return allowed[0]
        return value

    codepage = raw.get("EscposCodepage", profile["default_codepage"]).lower()
    if codepage not in profile["codepages"]:
        log("WARNING", f"code page {codepage!r} not available on {profile_name}, "
                       f"using {profile['default_codepage']}")
        codepage = profile["default_codepage"]
    codec, codepage_n = profile["codepages"][codepage]

    return Settings(
        profile_name=profile_name,
        profile=profile,
        cols=cols,
        codepage=codepage,
        codec=codec,
        codepage_n=codepage_n,
        left=bounded_int(env.get("ESCPOS_LEFT"), 0, 0, 50),
        right=bounded_int(env.get("ESCPOS_RIGHT"), 0, 0, 50),
        cut_feed_lines=bounded_int(env.get("ESCPOS_CUT_FEED_LINES"), 6, 0, 20),
        header=env.get("ESCPOS_HEADER", "")[:200],
        footer=env.get("ESCPOS_FOOTER", "")[:200],
        copies=bounded_int(argv[4] if len(argv) > 4 else None, 1, 1, MAX_COPIES),
        print_title=raw.get("PrintTitle", "true").lower() in ("true", "on", "yes", "1"),
        dots=dots,
        print_mode=choice("PrintMode", PRINT_MODES),
        dither=choice("Dither", DITHER_METHODS),
    )


# ---------- Safe characters ----------

# Always replaced, whatever the code page: invisible characters, Word's \x01
# bullets, and the U+FFFD that decoding errors leave behind.
ALWAYS_MAP = {
    "\x01": "*",
    "\u00ad": "",  # soft hyphen
    "\u200b": "", "\u200c": "", "\u200d": "", "\u2060": "", "\ufeff": "",
    "\ufffd": "?",
}

# Used only when the code page lacks the character
CHAR_MAP = {
    "\u2018": "'", "\u2019": "'", "\u201a": "'", "\u201b": "'", "\u2032": "'",
    "\u201c": '"', "\u201d": '"', "\u201e": '"', "\u201f": '"', "\u2033": '"',
    "\u2010": "-", "\u2011": "-", "\u2012": "-", "\u2013": "-", "\u2014": "-",
    "\u2015": "-", "\u2212": "-",
    "\u2022": "*", "\u2023": "*", "\u2043": "*", "\u25cf": "*", "\u25aa": "*",
    "\u25e6": "*", "\uf0b7": "*", "\uf0a7": "*",  # last two: Symbol/Wingdings bullets
    "\u2026": "...",
    "\u00a0": " ", "\u202f": " ", "\u3000": " ",
    "\u3001": ",", "\uff0c": ",", "\u3002": ".",
    "\u00a9": "(c)", "\u00ae": "(R)", "\u2122": "TM",
    "\u20ac": "EUR",
    # Letters with a stroke have no NFKD decomposition
    "\u0141": "L", "\u0142": "l", "\u00d8": "O", "\u00f8": "o",
    "\u0110": "D", "\u0111": "d", "\u0126": "H", "\u0127": "h",
}


@lru_cache(maxsize=4096)
def encodable(ch: str, codec: str) -> bool:
    try:
        ch.encode(codec)
        return True
    except UnicodeEncodeError:
        return False


def sanitize(s: str, codec: str) -> str:
    """Make text safe to send: no control bytes, only characters the code page has."""
    out = []
    for ch in s.expandtabs(8):
        if ch == "\n":
            out.append(ch)
        elif ch in ALWAYS_MAP:
            out.append(ALWAYS_MAP[ch])
        elif ord(ch) < 0x20 or 0x7f <= ord(ch) <= 0x9f:
            continue  # C0/C1 control: a stray ESC or GS would be read as a command
        elif encodable(ch, codec):
            out.append(ch)
        elif ch in CHAR_MAP:
            out.append(CHAR_MAP[ch])
        else:
            # Strip accents (Ł -> L), unfold compatibility forms (ﬁ -> fi)
            base = "".join(c for c in unicodedata.normalize("NFKD", ch)
                           if not unicodedata.combining(c))
            if base and all(encodable(c, codec) and ord(c) >= 0x20 for c in base):
                out.append(base)
            else:
                out.append("?")
    return "".join(out)


# ---------- ESC/POS output ----------

def encode_text(s: str, settings: Settings) -> bytes:
    return sanitize(s, settings.codec).encode(settings.codec, errors='replace')

def init_seq(settings: Settings) -> bytes:
    out = bytearray()
    out += ESC + b'@'              # Initialize
    out += ESC + b'M' + FONT_A     # Font A (0); Font B is \x01
    if DENSE_LINE_SPACING:
        out += ESC + b'3' + DENSE_LINE_SPACING_DOTS  # 22-dot line spacing (denser)
    else:
        out += ESC + b'2'            # Default line spacing
    out += ESC + b't' + bytes([settings.codepage_n])  # Code page
    return bytes(out)

def align_left() -> bytes:
    return ESC + b'a' + b'\x00'

def align_center() -> bytes:
    return ESC + b'a' + b'\x01'

def align_right() -> bytes:
    return ESC + b'a' + b'\x02'

def bold_on() -> bytes:
    return ESC + b'E' + b'\x01'

def bold_off() -> bytes:
    return ESC + b'E' + b'\x00'

def underline_on() -> bytes:
    return ESC + b'-' + b'\x01'

def underline_off() -> bytes:
    return ESC + b'-' + b'\x00'

def paper_cut(settings: Settings) -> bytes:
    """Paper cut using the profile's cut command"""
    return settings.profile["cut"]

def lf(n: int = 1) -> bytes:
    return b'\n' * n

def wrap_line(line: str, width: int) -> List[str]:
    # Preserve alignment markers & inline styles; strip them for wrapping width only.
    clean = line.replace('[CENTER]','').replace('[LEFT]','').replace('[RIGHT]','')
    clean = clean.replace('[B]','').replace('[/B]','').replace('[U]','').replace('[/U]','')
    return textwrap.wrap(clean, width=width, replace_whitespace=False) or [""]

def emit_line(line: str, settings: Settings) -> bytes:
    out = bytearray()
    # Alignment
    if line.startswith('[CENTER]'):
        out += align_center()
        line = line[len('[CENTER]'):]
    elif line.startswith('[RIGHT]'):
        out += align_right()
        line = line[len('[RIGHT]'):]
    else:
        out += align_left()
        if line.startswith('[LEFT]'):
            line = line[len('[LEFT]'):]
    # Inline styles (simple toggles around whole line)
    style_on = b''
    style_off = b''
    if line.startswith('[B]') and line.endswith('[/B]'):
        style_on += bold_on(); style_off += bold_off()
        line = line[3:-4]
    if line.startswith('[U]') and line.endswith('[/U]'):
        style_on += underline_on(); style_off += underline_off()
        line = line[3:-4]

    # Margins via spaces
    left_pad  = ' ' * settings.left
    right_pad = ' ' * settings.right

    # Wrap to cols minus margins
    inner_width = max(1, settings.cols - settings.left - settings.right)
    for seg in wrap_line(line, inner_width):
        out += style_on + encode_text(left_pad + seg + right_pad, settings) + style_off + lf()
    return bytes(out)

def notice(message: str, settings: Settings) -> bytes:
    """A short printed message, so a failed job still shows *something*."""
    out = init_seq(settings) + align_left() + encode_text(message, settings) + lf(2)
    if CUT_AT_JOB_END:
        out += lf(settings.cut_feed_lines) + paper_cut(settings)
    return out


# ---------- Document model ----------
# pdftohtml -xml gives text runs with position and font. Runs are grouped
# into lines, lines into segments (runs that read as one piece of text),
# and segments into blocks (consecutive lines of one paragraph or column).

@dataclass
class Run:
    text: str
    left: float
    top: float
    width: float
    height: float
    size: float
    bold: bool
    red: bool
    bullet: bool = False  # an empty run with a width: a Symbol-font bullet

@dataclass
class Segment:
    text: str
    left: float
    right: float
    top: float
    bottom: float
    size: float
    bold: bool
    red: bool
    page: int
    line_id: int

    @property
    def char_width(self) -> float:
        return max(1.0, (self.right - self.left) / max(1, len(self.text)))

    @property
    def height(self) -> float:
        return self.bottom - self.top

@dataclass
class Page:
    number: int
    width: float
    height: float
    segments: List[Segment]

@dataclass
class Block:
    segs: List[Segment]
    kind: str = ""  # "prose", "stacked" or "rows"

    @property
    def left(self) -> float:
        return min(s.left for s in self.segs)

    @property
    def right(self) -> float:
        return max(s.right for s in self.segs)

@dataclass
class PrintLine:
    """One printed line. raw lines go through emit_line so [B]/[CENTER] markers work."""
    text: str = ""
    align: str = "left"   # left, center, right
    bold: bool = False
    red: bool = False
    size: str = ""        # "", "2H" (double height) or "2W2H" (double width and height)
    raw: bool = False
    cut: bool = False
    image: bytes = b""    # raster commands for an image page

    @property
    def blank(self) -> bool:
        return not (self.text or self.cut or self.image)


BOLD_FONT = re.compile(r"bold|black|heavy|semibold|demi|[6-9]00", re.I)
MARKERS = ("[CENTER]", "[LEFT]", "[RIGHT]", "[B]", "[U]", "[CUT]")
PAGE_NUMBER = re.compile(r"^(page\s*)?\d{1,4}(\s*(of|/)\s*\d{1,4})?$", re.I)
RULE = re.compile(r"^([-_=*~.]\s?){3,}$")
BULLET = re.compile(r"^([*\u2022\u25cf\u25aa\u25e6\u2023\u2043\-\u2013]|\d{1,3}[.)]|[a-zA-Z][.)])\s+")
PRICE = re.compile(r"^(?P<label>.*?\S)\s*(?:\.{2,}|_{2,}|\s{3,})\s*"
                   r"(?P<value>[-+]?[$\u20ac\u00a3]?\s?[-\d][\d,]*(?:\.\d+)?)$")

# Font size relative to the body text, for headings
DOUBLE_SIZE_RATIO = 2.0
DOUBLE_HEIGHT_RATIO = 1.4
BOLD_HEADING_RATIO = 1.15
SMALL_TEXT_RATIO = 0.75   # smaller non-prose text (diagram labels) is dropped
MARGIN_ZONE = 0.08        # top/bottom share of the page checked for headers/footers


def is_red(color: str) -> bool:
    try:
        r, g, b = int(color[1:3], 16), int(color[3:5], 16), int(color[5:7], 16)
    except (ValueError, IndexError):
        return False
    return r >= 0x99 and g <= 0x66 and b <= 0x66

def collapse_repeats(s: str) -> str:
    """Undo fake bold, where the PDF draws each chunk twice: 'InInvvoicoicee' -> 'Invoice'."""
    out = []
    i = 0
    while i < len(s):
        for k in range((len(s) - i) // 2, 0, -1):
            if s[i:i + k] == s[i + k:i + 2 * k]:
                out.append(s[i:i + k])
                i += 2 * k
                break
        else:
            out.append(s[i])
            i += 1
    return "".join(out)

def parse_pdftohtml_xml(xml: bytes) -> List[Tuple[int, float, float, List[Run]]]:
    # XML can't carry control characters; keep Word's \x01 bullets as bullets
    xml = xml.replace(b"\x01", "\u2022".encode())
    xml = re.sub(rb"[\x00-\x08\x0b\x0c\x0e-\x1f]", b"", xml)
    root = ET.fromstring(xml)
    fonts: Dict[str, Tuple[float, str, str]] = {}
    pages = []
    for page_el in root.iter("page"):
        for fs in page_el.iter("fontspec"):
            fonts[fs.get("id", "")] = (float(fs.get("size", "0")), fs.get("family", ""),
                                       fs.get("color", "#000000"))
        runs = []
        for t in page_el.iter("text"):
            text = "".join(t.itertext())
            # pdftohtml writes Symbol-font bullets as empty elements with a width
            bullet = not text and float(t.get("width", "0")) > 2
            if not text.strip() and not bullet:
                continue
            size, family, color = fonts.get(t.get("font", ""), (0.0, "", "#000000"))
            height = float(t.get("height", "0"))
            runs.append(Run(
                text="\u2022" if bullet else text,
                left=float(t.get("left", "0")),
                top=float(t.get("top", "0")),
                width=float(t.get("width", "0")),
                height=height,
                size=size or height,
                bold=t.find(".//b") is not None or bool(BOLD_FONT.search(family)),
                red=is_red(color),
                bullet=bullet,
            ))
        pages.append((int(page_el.get("number", "0")), float(page_el.get("width", "0")),
                      float(page_el.get("height", "0")), runs))
    return pages

def run_char_width(r: Run) -> float:
    return max(1.0, r.width / max(1, len(r.text)))

def make_segment(runs: List[Run], page: int, line_id: int) -> Segment:
    parts = [runs[0].text]
    overlapped = False
    for a, b in zip(runs, runs[1:]):
        gap = b.left - (a.left + a.width)
        cw = min(run_char_width(a), run_char_width(b))
        if gap < -0.5 * cw:
            overlapped = True
        elif gap > 0.25 * cw and not parts[-1].endswith(" ") and not b.text.startswith(" "):
            parts.append(" ")
        parts.append(b.text)
    text = "".join(parts)
    if overlapped:
        text = collapse_repeats(text)
    text = re.sub(r"\s+", " ", text).strip()

    # Size, bold and red go by what most of the characters are
    by_size: Counter = Counter()
    bold_chars = red_chars = 0
    for r in runs:
        by_size[r.size] += len(r.text)
        bold_chars += len(r.text) if r.bold else 0
        red_chars += len(r.text) if r.red else 0
    total = sum(len(r.text) for r in runs)
    return Segment(
        text=text,
        left=min(r.left for r in runs),
        right=max(r.left + r.width for r in runs),
        top=min(r.top for r in runs),
        bottom=max(r.top + r.height for r in runs),
        size=by_size.most_common(1)[0][0],
        bold=bold_chars * 2 > total,
        red=red_chars * 2 > total,
        page=page,
        line_id=line_id,
    )

def build_segments(runs: List[Run], page: int, first_line_id: int) -> List[Segment]:
    # Group runs into lines: a run joins a line when its vertical centre falls
    # inside the line's tallest run, or the other way round. Superscripts and
    # small caps stay on their line.
    lines: List[List[Run]] = []
    for r in sorted(runs, key=lambda r: (r.top + r.height / 2, r.left)):
        if lines:
            ref = max(lines[-1], key=lambda x: x.height)
            if (ref.top <= r.top + r.height / 2 <= ref.top + ref.height
                    or r.top <= ref.top + ref.height / 2 <= r.top + r.height):
                lines[-1].append(r)
                continue
        lines.append([r])

    segments = []
    for n, line in enumerate(lines):
        line.sort(key=lambda r: r.left)
        # A bullet only counts at the start of a line with text after it
        line = [r for i, r in enumerate(line) if not r.bullet or (i == 0 and len(line) > 1)]
        if not line:
            continue
        groups = [[line[0]]]
        for r in line[1:]:
            prev = groups[-1][-1]
            gap = r.left - (prev.left + prev.width)
            # A wide gap separates table columns or side-by-side text,
            # but a bullet belongs with the text after it
            if not prev.bullet and gap > 2.0 * min(run_char_width(prev), run_char_width(r)):
                groups.append([r])
            else:
                groups[-1].append(r)
        segments += [make_segment(g, page, first_line_id + n) for g in groups]
    return [s for s in segments if s.text]

def extract_pages(xml: bytes) -> List[Page]:
    pages = []
    line_id = 0
    for number, width, height, runs in parse_pdftohtml_xml(xml):
        segs = build_segments(runs, number, line_id)
        line_id += len(runs) + 1
        pages.append(Page(number, width, height, segs))
    return pages


# ---------- Layout ----------

def body_size(pages: List[Page]) -> float:
    """The font size most of the text is set in."""
    sizes: Counter = Counter()
    for p in pages:
        for s in p.segments:
            sizes[s.size] += len(s.text)
    return sizes.most_common(1)[0][0] if sizes else 0.0

def drop_page_furniture(pages: List[Page]) -> None:
    """Remove page numbers, and running headers/footers repeated on other pages."""
    def key(s: Segment) -> str:
        return re.sub(r"\d+", "#", s.text.lower())

    def in_margin(s: Segment, p: Page) -> bool:
        return s.top < p.height * MARGIN_ZONE or s.bottom > p.height * (1 - MARGIN_ZONE)

    pages_with: Dict[str, set] = {}
    for p in pages:
        for s in p.segments:
            pages_with.setdefault(key(s), set()).add(p.number)

    for p in pages:
        keep = []
        for s in p.segments:
            if in_margin(s, p) and (PAGE_NUMBER.match(s.text) or len(pages_with[key(s)]) > 1):
                continue
            keep.append(s)
        p.segments = keep

def build_blocks(segs: List[Segment]) -> List[Block]:
    """Group consecutive lines of the same paragraph or column."""
    def standalone(s: Segment) -> bool:
        # Price lines and rules stay on their own lines
        return bool(PRICE.match(s.text) or RULE.match(s.text))

    blocks: List[Block] = []
    for s in sorted(segs, key=lambda s: (s.top, s.left)):
        for b in reversed(blocks[-40:] if not standalone(s) else []):
            last = b.segs[-1]
            if last.line_id == s.line_id or standalone(last):
                continue
            gap = s.top - last.bottom
            if not (-0.3 * s.height <= gap <= 0.6 * s.height):
                continue
            if abs(s.size - last.size) > 0.1 * last.size:
                continue
            cw = last.char_width
            same_left = abs(s.left - b.left) <= 1.5 * cw
            # The first line of a paragraph may be indented
            after_indent = len(b.segs) == 1 and 0 < b.left - s.left <= 6 * cw
            # A bullet item's wrapped lines are indented under its text
            under_bullet = (BULLET.match(last.text) is not None or any(
                BULLET.match(x.text) and abs(x.left - b.left) <= cw for x in b.segs[-3:])) \
                and 0 < s.left - b.left <= 6 * cw
            if (same_left or after_indent or under_bullet) and s.left <= b.right and s.right >= b.left:
                b.segs.append(s)
                break
        else:
            blocks.append(Block([s]))
    return blocks

def classify_blocks(blocks: List[Block]) -> None:
    lines_with_others: Dict[int, int] = Counter()
    for b in blocks:
        for s in b.segs:
            lines_with_others[s.line_id] += 1
    for b in blocks:
        mean_len = sum(len(s.text) for s in b.segs) / len(b.segs)
        if len(b.segs) >= 2 and mean_len >= 25:
            b.kind = "prose"
        elif len(b.segs) >= 2 and sum(lines_with_others[s.line_id] > 1 for s in b.segs) < 0.6 * len(b.segs):
            # A column of short lines (an address) that mostly doesn't line up with other text
            b.kind = "stacked"
        else:
            b.kind = "rows"

def size_style(size: float, body: float) -> Tuple[str, bool]:
    """(ESC ! size, bold) for text of this font size."""
    ratio = size / body if body else 1.0
    if ratio >= DOUBLE_SIZE_RATIO:
        return "2W2H", True
    if ratio >= DOUBLE_HEIGHT_RATIO:
        return "2H", True
    return "", ratio >= BOLD_HEADING_RATIO

def wrap(text: str, width: int, hang: int = 0, indent: int = 0) -> List[str]:
    return textwrap.wrap(text, width=max(1, width), initial_indent=" " * indent,
                         subsequent_indent=" " * (indent + hang),
                         break_long_words=True, break_on_hyphens=True) or [""]

def join_lines(texts: List[str]) -> str:
    """Join PDF lines into one paragraph, mending words hyphenated at line ends."""
    out = ""
    for t in texts:
        if re.search(r"[a-z]-$", out) and t[:1].islower():
            out = out[:-1] + t
        else:
            out = f"{out} {t}" if out else t
    return out

def split_paragraphs(block: Block) -> List[List[Segment]]:
    """Split a prose block where a line is short, starts a bullet, or is indented."""
    paras: List[List[Segment]] = []
    full_right = block.right
    for s in block.segs:
        first_word = len(s.text.split(" ", 1)[0]) + 1
        # Lines indented under a bullet item's text continue the item
        under_bullet = (paras and BULLET.match(paras[-1][0].text)
                        and s.left - paras[-1][0].left > 1.5 * s.char_width)
        new_para = (not paras
                    or BULLET.match(s.text)
                    or (not under_bullet and (
                        s.left - block.left > 1.5 * s.char_width
                        or full_right - paras[-1][-1].right > first_word * s.char_width)))
        if new_para:
            paras.append([s])
        else:
            paras[-1].append(s)
    return paras

def fit_row(segs: List[Segment], width: int) -> List[Tuple[str, int]]:
    """Lay out segments that share a line: [(text, hang)]. Spread them across
    the width in proportion to their gaps in the PDF if they fit, else stack."""
    texts = [s.text for s in segs]
    if len(segs) == 1:
        m = PRICE.match(texts[0])
        if not m:
            return [(texts[0], 2 if BULLET.match(texts[0]) else 0)]
        texts = [m.group("label"), m.group("value")]
        gaps = [1.0]
    else:
        gaps = [max(1.0, b.left - a.right) for a, b in zip(segs, segs[1:])]

    free = width - sum(len(t) for t in texts)
    if free >= len(gaps):
        spaces = [max(1, int(free * g / sum(gaps))) for g in gaps]
        spaces[-1] += free - sum(spaces)  # the last piece ends at the right edge
        line = texts[0] + "".join(" " * n + t for n, t in zip(spaces, texts[1:]))
        return [(line, 0)]
    if len(texts) == 2:
        # Label on its own line, value indented below
        return [(texts[0], 0), ("  " + texts[1], 2)]
    # First piece on its own line, the rest fitted (or stacked) below it
    rest = fit_row(segs[1:], width - 2)
    return [(texts[0], 0)] + [("  " + t, hang + 2) for t, hang in rest]

def segment_align(s: Segment, left: float, right: float) -> str:
    mid = (left + right) / 2
    width = right - left
    if width <= 0 or s.left - left < 0.1 * width:
        return "left"
    if abs((s.left + s.right) / 2 - mid) < 0.04 * width:
        return "center"
    if right - s.right < 0.02 * width:
        return "right"
    return "left"

def layout_pages(pages: List[Page], settings: Settings,
                 image_page: Callable[[int], List[PrintLine]]) -> List[PrintLine]:
    """Lay out every page; pages chosen by PrintMode come from image_page instead."""
    as_image = {p.number for p in pages
                if settings.print_mode == "image" or (settings.print_mode == "auto" and not p.segments)}
    drop_page_furniture(pages)
    body = body_size(pages)
    out: List[PrintLine] = []

    for p in pages:
        if p.number in as_image:
            out.append(PrintLine())
            out += image_page(p.number)
            continue
        blocks = build_blocks(p.segments)
        classify_blocks(blocks)

        # Small text that isn't running prose is diagram labels; leave it out
        for b in blocks:
            if b.kind != "prose":
                b.segs = [s for s in b.segs if s.size >= SMALL_TEXT_RATIO * body]
        blocks = [b for b in blocks if b.segs]
        kept = [s for b in blocks for s in b.segs]
        if not kept:
            continue
        left = min(s.left for s in kept)
        right = max(s.right for s in kept)

        # Items to print, each (top, bottom, lines). Rows group segments by line.
        items: List[Tuple[float, float, List[PrintLine]]] = []
        rows: Dict[int, List[Segment]] = {}
        for b in blocks:
            if b.kind == "rows":
                for s in b.segs:
                    rows.setdefault(s.line_id, []).append(s)
                continue
            lines: List[PrintLine] = []
            if b.kind == "prose":
                for para in split_paragraphs(b):
                    size, bold = size_style(max(s.size for s in para), body)
                    width = settings.cols // 2 if size == "2W2H" else settings.cols
                    text = join_lines([s.text for s in para])
                    hang = 0
                    m = BULLET.match(text)
                    if m:
                        text = m.group(1) + " " + text[m.end():]
                        hang = len(m.group(1)) + 1
                    bold = bold or sum(len(s.text) for s in para if s.bold) * 2 > len(text)
                    red = sum(len(s.text) for s in para if s.red) * 2 > len(text)
                    lines += [PrintLine(t, "left", bold, red, size) for t in wrap(text, width, hang)]
            else:
                size, bold = size_style(max(s.size for s in b.segs), body)
                red = any(s.red for s in b.segs)
                width = settings.cols // 2 if size == "2W2H" else settings.cols
                aligns = {segment_align(s, left, right) for s in b.segs}
                align = aligns.pop() if len(aligns) == 1 else "left"
                for s in b.segs:
                    lines += [PrintLine(t, align, bold or s.bold, red or s.red, size)
                              for t in wrap(s.text, width)]
            items.append((b.segs[0].top, b.segs[-1].bottom, lines))

        for segs in rows.values():
            segs.sort(key=lambda s: s.left)
            top = min(s.top for s in segs)
            bottom = max(s.bottom for s in segs)
            if len(segs) == 1 and segs[0].text.startswith(MARKERS):
                items.append((top, bottom, [PrintLine(segs[0].text, raw=True)]))
                continue
            if len(segs) == 1 and RULE.match(segs[0].text):
                items.append((top, bottom, [PrintLine("-" * settings.cols)]))
                continue
            size, bold = size_style(max(s.size for s in segs), body)
            bold = bold or sum(len(s.text) for s in segs if s.bold) * 2 > sum(len(s.text) for s in segs)
            red = any(s.red for s in segs)
            width = settings.cols // 2 if size == "2W2H" else settings.cols
            align = segment_align(segs[0], left, right) if len(segs) == 1 else "left"
            lines = []
            for text, hang in fit_row(segs, width):
                lines += [PrintLine(t, align, bold, red, size) for t in wrap(text, width, hang)]
            items.append((top, bottom, lines))

        items.sort(key=lambda it: it[0])
        prev_bottom: Optional[float] = None
        line_height = body * 1.2 or 12.0
        for top, bottom, lines in items:
            if prev_bottom is None:
                if out:
                    out.append(PrintLine())  # page break
            else:
                gap = top - prev_bottom
                # A blank line for paragraph spacing, or between side-by-side blocks
                if gap > 0.6 * line_height or gap < -0.5 * line_height:
                    out.append(PrintLine())
            out += lines
            prev_bottom = bottom
    return out

def layout_plain(text: str, settings: Settings) -> List[PrintLine]:
    """Fallback for pdftotext -layout output: remove the common indent, collapse
    blank lines, and keep [B]/[CENTER] style markers working."""
    lines = [l.rstrip() for l in text.splitlines()]
    indents = [len(l) - len(l.lstrip()) for l in lines if l.strip()]
    common = min(indents) if indents else 0
    out: List[PrintLine] = []
    for l in lines:
        l = l[common:]
        if not l.strip():
            if out and out[-1].text:
                out.append(PrintLine())
            continue
        if l.strip() == "[CUT]":
            out.append(PrintLine(cut=True))
        else:
            out.append(PrintLine(l, raw=True))
    return out


# ---------- Rendering ----------

SIZE_MODE = {"": 0x00, "2H": 0x10, "2W2H": 0x30}

def render_line(pl: PrintLine, settings: Settings) -> bytes:
    if pl.image:
        return align_left() + pl.image
    if pl.cut:
        return lf(2) + paper_cut(settings)
    if pl.raw:
        return emit_line(pl.text, settings)
    out = bytearray()
    out += {"center": align_center(), "right": align_right()}.get(pl.align, align_left())
    if pl.size:
        out += ESC + b'!' + bytes([SIZE_MODE[pl.size]])
    if pl.bold or (pl.red and not settings.profile["red"]):
        out += bold_on()
    if pl.red and settings.profile["red"]:
        out += ESC + b'r' + b'\x01'
    out += encode_text(pl.text, settings) + lf()
    if pl.red and settings.profile["red"]:
        out += ESC + b'r' + b'\x00'
    if pl.bold or pl.red:
        out += bold_off()
    if pl.size:
        out += ESC + b'!' + b'\x00'
    return bytes(out)

def tidy(lines: List[PrintLine]) -> List[PrintLine]:
    """Collapse runs of blank lines and trim them from both ends."""
    out: List[PrintLine] = []
    for pl in lines:
        if pl.blank and (not out or out[-1].blank):
            continue
        out.append(pl)
    while out and out[-1].blank:
        out.pop()
    return out

def render_document(lines: List[PrintLine], title: str, settings: Settings) -> bytes:
    """Render one copy of the document, ending with the cut."""
    out = bytearray()
    out += init_seq(settings)

    if settings.header:
        out += align_center() + bold_on() + encode_text(settings.header, settings) + bold_off() + lf()

    # Optional title line (trim to width). Photos and other image-only
    # documents print just the image.
    if title and settings.print_title and any(pl.text for pl in lines):
        out += align_center() + underline_on() + encode_text(title, settings)[:settings.cols] + underline_off() + lf(2)

    for pl in tidy(lines):
        out += render_line(pl, settings)

    if settings.footer:
        out += lf() + align_center() + encode_text(settings.footer, settings) + lf()

    if CUT_AT_JOB_END:
        out += lf(settings.cut_feed_lines) + paper_cut(settings)
    return bytes(out)


# ---------- Images ----------
# Pages without text (photos, scans, QR codes) are rendered with pdftoppm,
# cropped to what's drawn, scaled to the paper width and dithered to 1 bit.

RASTER_BAND_ROWS = 256  # rows per GS v 0 command, to keep each one small
MAX_IMAGE_ROWS = 4000   # about 50cm at 203 dpi, so one page can't run on for metres
INVERT = bytes(255 - i for i in range(256))

def render_page_gray(pdf_path: str, page: int, dpi: float,
                     crop: Optional[Tuple[int, int, int, int]] = None) -> "Image.Image":
    cmd = ["pdftoppm", "-gray", "-r", f"{dpi:.2f}", "-f", str(page), "-l", str(page), "-singlefile"]
    if crop:
        x, y, w, h = crop
        cmd += ["-x", str(x), "-y", str(y), "-W", str(w), "-H", str(h)]
    cmd.append(pdf_path)
    return Image.open(io.BytesIO(run_poppler(cmd))).convert("L")

def page_image(pdf_path: str, page: int, dots: int) -> Optional["Image.Image"]:
    """The page's drawn area as grayscale, exactly `dots` wide, or None if blank."""
    # At 72 dpi one pixel is one point: find the drawn area, then render just
    # that area at the resolution that makes it as wide as the paper.
    preview = render_page_gray(pdf_path, page, 72)
    bbox = ImageOps.invert(preview).point(lambda v: 255 if v > 8 else 0).getbbox()
    if not bbox:
        return None
    left, top, right, bottom = bbox
    dpi = min(1200.0, 72.0 * dots / max(1, right - left))
    scale = dpi / 72
    img = render_page_gray(pdf_path, page, dpi, (
        int(left * scale), int(top * scale),
        int((right - left) * scale) + 1, int((bottom - top) * scale) + 1))

    return fit_width(img, dots)

def choose_dither(img: "Image.Image", setting: str) -> str:
    """Auto: threshold images that are almost all black and white (QR codes,
    barcodes, logos, line art) so edges stay sharp; Atkinson for the rest."""
    if setting != "auto":
        return setting
    hist = img.histogram()
    extreme = sum(hist[:64]) + sum(hist[192:])
    return "threshold" if extreme >= 0.9 * sum(hist) else "atkinson"

def atkinson(img: "Image.Image") -> "Image.Image":
    """Atkinson dithering: pass 6/8 of the error to 6 neighbours. Light areas
    stay clean and contrast stays high, which suits dot gain on receipt paper."""
    w, h = img.size
    px = list(img.getdata())
    for y in range(h):
        row = y * w
        for x in range(w):
            i = row + x
            old = px[i]
            new = 0 if old < 128 else 255
            px[i] = new
            e = (old - new) // 8
            if not e:
                continue
            if x + 1 < w:
                px[i + 1] += e
                if x + 2 < w:
                    px[i + 2] += e
            if y + 1 < h:
                if x > 0:
                    px[i + w - 1] += e
                px[i + w] += e
                if x + 1 < w:
                    px[i + w + 1] += e
                if y + 2 < h:
                    px[i + 2 * w] += e
    out = Image.new("L", (w, h))
    out.putdata(px)
    return out.convert("1", dither=Image.Dither.NONE)

def dither(img: "Image.Image", method: str) -> "Image.Image":
    if method == "threshold":
        return img.point(lambda v: 255 if v >= 128 else 0).convert("1", dither=Image.Dither.NONE)
    if method == "floyd-steinberg":
        return img.convert("1")  # Pillow's default is Floyd-Steinberg
    return atkinson(img)

def raster_commands(bw: "Image.Image") -> bytes:
    """GS v 0 raster commands for a 1-bit image whose width is a multiple of 8."""
    row_bytes = bw.width // 8
    # Pillow packs 1 as white; the printer wants 1 as black
    data = bw.tobytes().translate(INVERT)
    out = bytearray()
    for y in range(0, bw.height, RASTER_BAND_ROWS):
        rows = min(RASTER_BAND_ROWS, bw.height - y)
        out += GS + b'v0' + b'\x00' + bytes([row_bytes & 0xFF, row_bytes >> 8, rows & 0xFF, rows >> 8])
        out += data[y * row_bytes:(y + rows) * row_bytes]
    return bytes(out)

def fit_width(img: "Image.Image", dots: int) -> "Image.Image":
    """Scale to exactly `dots` wide; if that's too tall, shrink to fit and center."""
    height = max(1, round(img.height * dots / img.width))
    if height <= MAX_IMAGE_ROWS:
        return img.resize((dots, height), Image.Resampling.LANCZOS)
    width = max(8, round(img.width * MAX_IMAGE_ROWS / img.height))
    canvas = Image.new("L", (dots, MAX_IMAGE_ROWS), 255)
    canvas.paste(img.resize((width, MAX_IMAGE_ROWS), Image.Resampling.LANCZOS), ((dots - width) // 2, 0))
    return canvas

def image_lines(img: "Image.Image", settings: Settings, what: str) -> List[PrintLine]:
    """Prepare and dither a grayscale image that is already the paper width."""
    img = ImageOps.autocontrast(img, cutoff=1)
    method = choose_dither(img, settings.dither)
    if method != "threshold":
        gamma = settings.profile["image_gamma"]
        img = img.point([round(255 * (i / 255) ** gamma) for i in range(256)])
    log("DEBUG", f"{what}: image {img.width}x{img.height}, {method}")
    return [PrintLine(image=raster_commands(dither(img, method)))]

def image_page_lines(pdf_path: str, page: int, settings: Settings) -> List[PrintLine]:
    if Image is None:
        log("WARNING", "python3-pil is not installed, so image pages can't print")
        return [PrintLine(f"[page {page}: image not printed]")]
    img = page_image(pdf_path, page, settings.dots - settings.dots % 8)
    if img is None:
        return []
    return image_lines(img, settings, f"page {page}")

def image_file_lines(path: str, settings: Settings) -> List[PrintLine]:
    """A JPEG or PNG sent straight to the queue (phone photos). CUPS's own
    image filter would crop it to fill the long receipt page, so the PPD
    routes images here and the whole picture prints at the paper width."""
    if Image is None:
        raise RuntimeError("python3-pil is not installed, so images can't print")
    dots = settings.dots - settings.dots % 8
    img = Image.open(path)
    # Decode big JPEGs at a reduced scale; any side of at least `dots` is plenty
    img.draft("RGB", (dots, dots))
    img = ImageOps.exif_transpose(img)
    if img.mode in ("RGBA", "LA", "P"):
        # Transparent areas print as white paper
        img = img.convert("RGBA")
        background = Image.new("RGBA", img.size, (255, 255, 255, 255))
        img = Image.alpha_composite(background, img)
    return image_lines(fit_width(img.convert("L"), dots), settings, "image file")


# ---------- PDF extraction ----------

def validate_pdf_path(pdf_path: str) -> bool:
    """Validate that the PDF path is safe and the file exists."""
    try:
        # Basic path validation
        if not pdf_path or '..' in pdf_path:
            return False
        # Check if file exists and is readable
        return os.path.isfile(pdf_path) and os.access(pdf_path, os.R_OK)
    except OSError:
        return False

def run_poppler(cmd: List[str]) -> bytes:
    try:
        return subprocess.check_output(cmd, stderr=subprocess.DEVNULL, timeout=30)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"{cmd[0]} failed: {e}")
    except subprocess.TimeoutExpired:
        raise RuntimeError(f"{cmd[0]} timed out")

def extract_print_lines(pdf_path: str, settings: Settings) -> List[PrintLine]:
    """Lay out the PDF's text from pdftohtml's positions and fonts, falling
    back to pdftotext -layout if that fails."""
    if not validate_pdf_path(pdf_path):
        raise ValueError(f"Invalid or inaccessible PDF path: {pdf_path}")
    try:
        pages = extract_pages(run_poppler(["pdftohtml", "-xml", "-i", "-q", "-stdout", pdf_path]))
        lines = layout_pages(pages, settings, lambda n: image_page_lines(pdf_path, n, settings))
        log("DEBUG", f"laid out {len(pages)} page(s) from pdftohtml -xml")
        return lines
    except Exception as e:
        log("WARNING", f"pdftohtml layout failed ({e}), falling back to pdftotext")
    # -layout keeps columns reasonably intact; -nopgbrk avoids page-break characters
    text = run_poppler(["pdftotext", "-layout", "-nopgbrk", "-enc", "UTF-8", pdf_path, "-"])
    return layout_plain(text.decode("utf-8", errors="replace"), settings)

def main() -> None:
    # CUPS filter args:
    # argv[0] = program
    # argv[1] = job-id
    # argv[2] = user
    # argv[3] = title
    # argv[4] = copies
    # argv[5] = options
    # argv[6] = filename (or data on stdin if absent or "-")
    # The input is a PDF, or a JPEG/PNG image (see the PPD's cupsFilter lines).
    job_id  = sys.argv[1] if len(sys.argv) > 1 else "-"
    title   = sys.argv[3] if len(sys.argv) > 3 else ""
    infile  = sys.argv[6] if len(sys.argv) > 6 else "-"

    settings = resolve_settings(sys.argv, dict(os.environ))
    log("DEBUG", f"job {job_id}: profile={settings.profile_name} cols={settings.cols} "
                 f"codepage={settings.codepage} (ESC t {settings.codepage_n}) copies={settings.copies}")

    # Get PDF bytes to a temp file if needed
    temp_file_created = False
    if infile == "-":
        # Read from stdin
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix=".pdf") as tf:
            tf.write(sys.stdin.buffer.read())
            pdf_path = tf.name
            temp_file_created = True
    elif os.path.exists(infile):
        # Use provided file
        pdf_path = infile
    else:
        # File doesn't exist - this is an error
        log("ERROR", f"PDF file '{infile}' not found")
        sys.stdout.buffer.write(notice(f"Error: PDF file '{infile}' not found", settings))
        sys.exit(1)

    try:
        with open(pdf_path, "rb") as f:
            magic = f.read(8)
        if magic.startswith((b"\xff\xd8\xff", b"\x89PNG")):
            lines = image_file_lines(pdf_path, settings)
        else:
            lines = extract_print_lines(pdf_path, settings)
    except Exception as e:
        # If extraction fails, emit a minimal notice so the receipt shows *something*
        log("ERROR", f"text extraction failed: {e}")
        sys.stdout.buffer.write(notice("Unable to extract text from PDF.", settings))
        sys.exit(0)
    finally:
        # Clean up temp file
        if temp_file_created and os.path.exists(pdf_path):
            try:
                os.unlink(pdf_path)
            except OSError:
                pass  # Ignore cleanup errors

    if all(pl.blank for pl in lines):
        log("INFO", "PDF has no text")
        sys.stdout.buffer.write(notice("This PDF has no text to print.", settings))
        sys.exit(0)

    # The PPD sets cupsManualCopies, so copies are ours to print
    document = render_document(lines, title, settings)
    for _ in range(settings.copies):
        sys.stdout.buffer.write(document)

if __name__ == "__main__":
    main()
